def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    div_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    div_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def regions(length, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < length:
            result.append((start, length))
        return result

    row_regions = regions(h, div_rows)
    col_regions = regions(w, div_cols)
    blocks = [(r0, r1, c0, c1)
              for r0, r1 in row_regions
              for c0, c1 in col_regions]

    source = max(
        blocks,
        key=lambda b: sum(
            grid[r][c] != background
            for r in range(b[0], b[1])
            for c in range(b[2], b[3])
        )
    )
    sr0, sr1, sc0, sc1 = source
    pattern = [
        [grid[r][c] for c in range(sc0, sc1)]
        for r in range(sr0, sr1)
    ]

    out = [row[:] for row in grid]
    for r0, r1 in row_regions:
        for c0, c1 in col_regions:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    rr, cc = r - r0, c - c0
                    out[r][c] = pattern[rr][cc] if rr < len(pattern) and cc < len(pattern[0]) else background

    return out
